/*
 * ESP-NOW Dual LED Control — Board 1 (Sender)
 *
 * Every 2 seconds, toggles a command and sends it to
 * Board 2 via ESP-NOW. Green LED on D2 blinks on each send.
 * A 3-second startup delay gives Board 2 time to register.
 *
 * Circuit:
 *   D2 -> Green LED -> 220 ohm -> GND
 */

#include <esp_now.h>
#include <WiFi.h>

uint8_t receiverMAC[] = {0xAA, 0xBB, 0xCC, 0xDD, 0xEE, 0x02};

esp_now_peer_info_t peerInfo;

#define CMD_LED_ON   1
#define CMD_LED_OFF  0

int ledState = 0;

void onSendDone(const uint8_t *mac, esp_now_send_status_t status) {
  Serial.print("Send: ");
  Serial.println(status == ESP_NOW_SEND_SUCCESS ? "OK" : "FAIL");
}

void setup() {
  Serial.begin(115200);
  pinMode(2, OUTPUT);

  WiFi.mode(WIFI_STA);
  Serial.print("Sender MAC: ");
  Serial.println(WiFi.macAddress());

  esp_now_init();
  esp_now_register_send_cb(onSendDone);

  memcpy(peerInfo.peer_addr, receiverMAC, 6);
  peerInfo.channel = 0;
  peerInfo.encrypt = false;
  esp_now_add_peer(&peerInfo);

  Serial.println("Sender ready — waiting 3s for receiver...");
  delay(3000);
}

void loop() {
  ledState = !ledState;
  int cmd = ledState ? CMD_LED_ON : CMD_LED_OFF;

  esp_now_send(receiverMAC, (uint8_t *)&cmd, sizeof(cmd));

  digitalWrite(2, HIGH);
  delay(100);
  digitalWrite(2, LOW);

  Serial.print("Sent: ");
  Serial.println(cmd ? "LED_ON" : "LED_OFF");

  delay(2000);
}
